namespace A33.Instrument.Protocol;
public sealed class ModbusClient(IModbusTransport transport,byte unit=1) { private readonly SemaphoreSlim gate=new(1,1); private ushort tid; public async Task<ushort[]> ReadHoldingAsync(ushort address,ushort count,CancellationToken ct=default){await gate.WaitAsync(ct);try{var request=ModbusRequestCodec.ReadHolding(unit,address,count);var adu=ModbusTcpCodec.Encode(++tid,unit,request.AsSpan(1));var response=await transport.ExchangeAsync(adu,ct);var (_,_,rpdu)=ModbusTcpCodec.Decode(response.Span,tid);return ModbusResponseCodec.ReadHolding(rpdu.Span);}finally{gate.Release();}} }
